#!/usr/bin/env node
import { execFileSync } from "node:child_process";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

type Label = { name: string; color: string; description: string };

const repoRoot = resolve(import.meta.dirname, "..", "..");
const labelerPath = resolve(repoRoot, ".github/labeler.yml");
const labelsPath = resolve(repoRoot, ".github/labels.yml");
const specsDir = resolve(repoRoot, "specs");

const AUTO_BEGIN =
  "# AUTO-GENERATED BEGIN — component:* entries generated by scripts/sync-labels.ts";
const AUTO_END = "# AUTO-GENERATED END";
const COMPONENT_LABEL_COLOR = "d4c5f9";

function readComponents(): string[] {
  const entries = readdirSync(specsDir, { withFileTypes: true });
  const names: string[] = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!entry.name.endsWith(".yaml")) continue;
    const base = entry.name.slice(0, -".yaml".length);
    if (base.startsWith("_")) continue;
    names.push(base);
  }
  return names.sort();
}

function renderComponentEntries(components: string[]): string {
  if (components.length === 0) return "";
  const lines: string[] = [];
  for (const name of components) {
    lines.push(`component:${name}:`);
    lines.push("  - changed-files:");
    lines.push("      - any-glob-to-any-file:");
    lines.push(`          - packages/css/src/components/${name}/**`);
    lines.push(`          - specs/${name}.yaml`);
    lines.push("");
  }
  return lines.join("\n");
}

function renderComponentLabels(components: string[]): string {
  return components
    .map(
      (name) =>
        `- name: component:${name}\n  color: ${COMPONENT_LABEL_COLOR}\n  description: ${name} component`,
    )
    .join("\n");
}

function injectAutoRegion(current: string, body: string, path: string): string {
  const beginIdx = current.indexOf(AUTO_BEGIN);
  const endIdx = current.indexOf(AUTO_END);
  if (beginIdx === -1 || endIdx === -1) {
    throw new Error(`Could not find AUTO-GENERATED markers in ${path}`);
  }
  const before = current.slice(0, beginIdx + AUTO_BEGIN.length);
  const after = current.slice(endIdx);
  return `${before}${body}${after}`;
}

function replaceAutoRegion(path: string, body: string): void {
  const current = readFileSync(path, "utf8");
  writeFileSync(path, injectAutoRegion(current, body, path));
}

function labelerBody(components: string[]): string {
  const generated = renderComponentEntries(components);
  return generated ? `\n${generated}` : "\n";
}

function labelsBody(components: string[]): string {
  const generated = renderComponentLabels(components);
  return generated ? `\n${generated}\n` : "\n";
}

function regenerateLabeler(): void {
  const components = readComponents();
  replaceAutoRegion(labelerPath, labelerBody(components));
  console.log(
    `labeler.yml: regenerated ${components.length} component entr${components.length === 1 ? "y" : "ies"}`,
  );
}

function regenerateLabels(): void {
  const components = readComponents();
  replaceAutoRegion(labelsPath, labelsBody(components));
  console.log(
    `labels.yml: regenerated ${components.length} component label${components.length === 1 ? "" : "s"}`,
  );
}

function checkDrift(): boolean {
  const components = readComponents();
  const labelerCurrent = readFileSync(labelerPath, "utf8");
  const labelsCurrent = readFileSync(labelsPath, "utf8");
  const labelerExpected = injectAutoRegion(labelerCurrent, labelerBody(components), labelerPath);
  const labelsExpected = injectAutoRegion(labelsCurrent, labelsBody(components), labelsPath);
  const drifted: string[] = [];
  if (labelerCurrent !== labelerExpected) drifted.push(".github/labeler.yml");
  if (labelsCurrent !== labelsExpected) drifted.push(".github/labels.yml");
  if (drifted.length === 0) return false;
  console.error(
    `sync-labels drift detected in: ${drifted.join(", ")}\n` +
      `Run: node scripts/repo/sync-labels.ts --mode=generate\n` +
      `Then commit the regenerated files.`,
  );
  return true;
}

function parseLabelsYaml(): Label[] {
  const raw = readFileSync(labelsPath, "utf8");
  const lines = raw.split("\n");
  const labels: Label[] = [];
  let current: Partial<Label> | null = null;
  for (const line of lines) {
    if (line.startsWith("- name:")) {
      if (current?.name) labels.push(current as Label);
      current = { name: line.slice("- name:".length).trim() };
    } else if (line.startsWith("  color:") && current) {
      current.color = line.slice("  color:".length).trim();
    } else if (line.startsWith("  description:") && current) {
      current.description = line.slice("  description:".length).trim();
    }
  }
  if (current?.name) labels.push(current as Label);
  for (const label of labels) {
    if (!label.color || label.description === undefined) {
      throw new Error(`Malformed label entry: ${JSON.stringify(label)}`);
    }
  }
  return labels;
}

function listRemoteLabels(): Map<string, { color: string; description: string }> {
  const out = execFileSync(
    "gh",
    ["label", "list", "--limit", "200", "--json", "name,color,description"],
    {
      encoding: "utf8",
    },
  );
  const parsed: Array<{ name: string; color: string; description: string }> = JSON.parse(out);
  const map = new Map<string, { color: string; description: string }>();
  for (const entry of parsed) {
    map.set(entry.name, { color: entry.color, description: entry.description ?? "" });
  }
  return map;
}

function upsertLabels(): void {
  const desired = parseLabelsYaml();
  const remote = listRemoteLabels();
  let created = 0;
  let updated = 0;
  let unchanged = 0;
  for (const label of desired) {
    const existing = remote.get(label.name);
    if (!existing) {
      execFileSync(
        "gh",
        ["label", "create", label.name, "--color", label.color, "--description", label.description],
        { stdio: "inherit" },
      );
      created += 1;
      continue;
    }
    if (
      existing.color.toLowerCase() === label.color.toLowerCase() &&
      existing.description === label.description
    ) {
      unchanged += 1;
      continue;
    }
    execFileSync(
      "gh",
      ["label", "edit", label.name, "--color", label.color, "--description", label.description],
      { stdio: "inherit" },
    );
    updated += 1;
  }
  console.log(`labels: ${created} created, ${updated} updated, ${unchanged} unchanged`);
}

if (process.argv.includes("--check")) {
  process.exit(checkDrift() ? 1 : 0);
}

const modeArg = process.argv.find((arg) => arg.startsWith("--mode="));
const mode = modeArg ? modeArg.slice("--mode=".length) : "both";

if (mode === "generate" || mode === "both") {
  regenerateLabeler();
  regenerateLabels();
}
if (mode === "upsert" || mode === "both") {
  upsertLabels();
}
if (!["generate", "upsert", "both"].includes(mode)) {
  console.error(`Unknown --mode: ${mode}. Expected generate, upsert, or both.`);
  process.exit(1);
}
